div.script:
(() => {
	const camera = document.currentScript.currentDMCamera;
	const context = camera && camera.exportToUI;
	if (!context) {
		console.error("[minimal-ui] exportToUI missing");
		return;
	}
	const ui = camera.getUIElement();
	const status = ui.querySelector(".mini-status");
	const set = (text) => {
		if (status) status.textContent = text;
	};

	set(
		`[custom] scan the ${context.session.currentSide === "backSide" ? "BACK" : "FRONT"}`,
	);
	context.engine.on("hint", ({ hint }) => set(`[custom] ${hint}`));
	context.session.on("flipPrompt", () => {
		set("[custom] FLIP THE CARD");
		setTimeout(() => context.session.confirmFlip(), 1500);
	});
	// Capture confirmation is on by default; without a confirmation
	// screen of its own, this UI accepts every capture.
	context.session.on("confirmationPrompt", () => context.session.confirm());
	context.session.on("stateChanged", ({ current }) => {
		if (["completed", "rejected", "cancelled"].includes(current)) {
			set(`[custom] ${current}`);
		}
	});
	ui.querySelector(".mini-cancel")?.addEventListener("click", () => context.close());
})();
